    for (int i = 1; i <= 9; i++) {
        if (i <= high) {
            queue.offer((long) i);
        }
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num >= low && num <= high) {
            result.add((int) num);
        }
        if (num > high) {
            continue;
