public static int squarePermutations(int[] A) {
    int n = A.length;
    int fullMask = (1 << n) - 1;
    int[][] memo = new int[1 << n][n];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(memo[i], -1);
    }

    java.util.function.IntBinaryOperator isSquare = sum -> {
        int r = (int) Math.sqrt(sum);
        return r * r == sum ? 1 : 0;
    };

    java.util.function.IntUnaryOperator dfs = new java.util.function.IntUnaryOperator() {
        @Override
        public int applyAsInt(int mask) {
            return dfsWithLast(mask, -1);
        }

        private int dfsWithLast(int mask, int last) {
            if (mask == 0) return 1;
            if (last != -1 && memo[mask][last] != -1) return memo[mask][last];
            int res = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    if (last == -1 || isSquare.applyAsInt(A[last] + A[i]) == 1) {
                        res += dfsWithLast(mask ^ (1 << i), i);
                    }
                }
            }
            if (last != -1) memo[mask][last] = res;
            return res;
        }
    };

    return dfs.applyAsInt(fullMask);
}

